  static let sections: [String: [String]] = {
    guard let packed = Data(base64Encoded: encoded),
      let text = try? (packed as NSData).decompressed(using: .zlib) as Data,
      let lines = String(data: text, encoding: .utf8)?.split(separator: "\n")
    else { return [:] }
    var result: [String: [String]] = [:]
    var current = ""
    for line in lines {
      if line.hasPrefix("["), line.hasSuffix("]") {
        current = String(line.dropFirst().dropLast())
      } else {
        result[current, default: []].append(String(line))
      }
    }
    return result
  }()

  static func document() -> [String] { sections["document"] ?? [] }

  static func title(_ role: String) -> [String] { sections[role] ?? [] }
}
